def bind(adapters, modules):
    import hashlib,json,math,copy,base64
    if set(adapters)!=set(ADAPTER_NAMES) or set(modules)!=set(MODULE_NAMES):
        raise ValueError("incomplete local source state contract")
    namespace=dict(adapters, **modules, hashlib=hashlib,json=json,math=math,copy=copy,base64=base64)
    exec(compile(PROGRAM,"<source-state-kernel>","exec"),namespace)
    return namespace
